statsLine(properties) {
    const hasProblemCount = properties.problemCount !== undefined && properties.problemCount !== null
    const hasGradeRange = properties.gradeMin && properties.gradeMax
    if (!hasProblemCount && !hasGradeRange) return null

    const row = document.createElement("div")
    row.className = "flex flex-wrap items-center gap-2 text-sm"

    if (hasProblemCount) {
        const count = document.createElement("span")
        count.className = "inline-flex items-center rounded-full bg-brand-50 px-2.5 py-1 font-medium text-brand-700"
        count.textContent = `${properties.problemCount} ${this.strings.problems}`
        row.appendChild(count)
    }

    if (hasGradeRange) {
