/**
 * Builds the problem-count and compact grade-range chart when data is present.
 * @param {Object} properties Tile feature properties.
 * @returns {HTMLElement|null} Stats line element or null.
 */
statsLine(properties) {
    const hasProblemCount = properties.problemCount !== undefined && properties.problemCount !== null
    const gradeChart = this.gradeRangeChart(properties.gradeMin, properties.gradeMax)
    if (!hasProblemCount && !gradeChart) return null

    const section = document.createElement("div")
    section.className = "space-y-2"

    if (hasProblemCount) {
        const count = document.createElement("p")
        count.className = "text-sm font-medium text-gray-700"
        count.textContent = `${properties.problemCount} ${this.strings.problems}`
        section.appendChild(count)
    }

    if (gradeChart) section.appendChild(gradeChart)
    return section
}

/**
 * Builds a small 1–8 grade range indicator using the tile contract's min/max
 * grades. Tiles do not currently carry distribution counts, so this mirrors
 * the existing area grade chart visually as a highlighted range, not a histogram.
 * @param {string} gradeMin Minimum grade string.
 * @param {string} gradeMax Maximum grade string.
 * @returns {HTMLElement|null} Grade range chart or null.
 */
gradeRangeChart(gradeMin, gradeMax) {
    const minLevel = this.gradeLevel(gradeMin)
    const maxLevel = this.gradeLevel(gradeMax)
    if (!minLevel || !maxLevel) return null

    const low = Math.min(minLevel, maxLevel)
    const high = Math.max(minLevel, maxLevel)
    const chart = document.createElement("div")
    chart.className = "rounded-lg bg-gray-50 p-2"
    chart.setAttribute("aria-label", `${gradeMin} – ${gradeMax}`)

    const bars = document.createElement("div")
    bars.className = "flex h-8 items-end gap-1"
    GRADE_LEVELS.forEach((level) => {
        const bar = document.createElement("div")
        const active = level >= low && level <= high
        bar.className = `${active ? "bg-brand-500" : "bg-gray-200"} flex-1 rounded-sm`
        bar.style.height = `${10 + (level * 3)}px`
        bars.appendChild(bar)
    })
    chart.appendChild(bars)

    const labels = document.createElement("div")
    labels.className = "mt-1 flex justify-between text-[10px] font-medium text-gray-500"
    GRADE_LEVELS.forEach((level) => {
        const label = document.createElement("span")
        label.textContent = level.toString()
        labels.appendChild(label)
    })
    chart.appendChild(labels)

    const range = document.createElement("p")
    range.className = "mt-1 text-xs font-semibold text-gray-700"
    range.textContent = `${gradeMin} – ${gradeMax}`
    chart.appendChild(range)
    return chart
}

/**
 * Extracts the Font grade level digit used by the site's 1–8 charts.
 * @param {string} grade Grade string such as "6a+".
 * @returns {number|null} Grade level or null.
 */
gradeLevel(grade) {
    const match = String(grade || "").match(/^[1-8]/)
    return match ? Number(match[0]) : null
}

