            const enabled = level >= low && level <= high
            const badge = document.createElement("span")
            badge.className = "ml-1 inline-flex h-4 w-4 justify-center rounded-sm text-sm leading-4 text-white"
            badge.style.backgroundColor = enabled ? "rgba(5, 150, 105, 0.8)" : "rgba(204, 204, 204, .5)"
            badge.textContent = level.toString()
            levels.appendChild(badge)
        })
        wrapper.appendChild(levels)

        const range = document.createElement("span")
        range.className = "text-xs font-semibold text-gray-600"
        range.textContent = `${gradeMin} – ${gradeMax}`
        wrapper.appendChild(range)
        return wrapper
    }

    /**
     * Extracts the Font grade level digit used by the site's grade charts.
     * @param {string} grade Grade string such as "6a+".
     * @returns {number|null} Grade level or null.
     */
    gradeLevel(grade) {
        const match = String(grade || "").match(/^[1-9]/)
        return match ? Number(match[0]) : null
    }

    /**
