/**
 * Adds a tiny damped horizontal wiggle to selected symbol layers.
 * @param {Object} config Selectable kind configuration.
 * @param {number} progress Tween progress, clamped 0..1.
 * @returns {void}
 */
applyIconWiggle(config, progress) {
    if (!this.map.getLayer(config.selectedLayerId)) return

    const base = this.originalIconOffset(config)
    const amplitude = ICON_WIGGLE_PX * Math.max(0, 1 - progress)
    const x = base[0] + (Math.sin(progress * Math.PI * 4) * amplitude)
    const y = base[1] - (Math.sin(progress * Math.PI) * amplitude * 0.5)
    this.map.setLayoutProperty(config.selectedLayerId, "icon-offset", [x, y])
}

