    /**
     * Builds the problem-count and compact grade-range chart when data is present.
     * @param {Object} properties Tile feature properties.
     * @returns {HTMLElement|null} Stats line element or null.
     */
    statsLine(properties) {
        const hasProblemCount = properties.problemCount !== undefined && properties.problemCount !== null
        const gradeChart = this.gradeRangeChart(properties.gradeMin, properties.gradeMax)
        if (!hasProblemCount && !gradeChart) return null

        const section = document.createElement("div")
        section.className = "space-y-2"

        if (hasProblemCount) {
            const count = document.createElement("p")
            count.className = "text-sm font-medium text-gray-700"
            count.textContent = `${properties.problemCount} ${this.strings.problems}`
            section.appendChild(count)
        }

        if (gradeChart) section.appendChild(gradeChart)
        return section
    }

    /**
     * Builds a compact, tasteful segmented difficulty bar. Tiles do not carry
     * per-level distribution counts, so levels between `gradeMin` and
     * `gradeMax` are highlighted as the available range.
     * @param {string} gradeMin Minimum grade string.
     * @param {string} gradeMax Maximum grade string.
     * @returns {HTMLElement|null} Grade range indicator or null.
     */
    gradeRangeChart(gradeMin, gradeMax) {
        const minLevel = this.gradeLevel(gradeMin)
        const maxLevel = this.gradeLevel(gradeMax)
        if (!minLevel || !maxLevel) return null

        const low = Math.min(minLevel, maxLevel)
        const high = Math.max(minLevel, maxLevel)
        const wrapper = document.createElement("div")
        wrapper.className = "space-y-1.5 rounded-lg bg-gray-50 p-2"
        wrapper.setAttribute("aria-label", `${gradeMin} – ${gradeMax}`)

        const header = document.createElement("div")
        header.className = "flex items-baseline justify-between"
        const label = document.createElement("span")
        label.className = "text-xs font-medium uppercase tracking-wide text-gray-500"
        label.textContent = this.strings.grades
        header.appendChild(label)
        const range = document.createElement("span")
        range.className = "text-sm font-semibold text-gray-800"
        range.textContent = `${gradeMin} – ${gradeMax}`
        header.appendChild(range)
        wrapper.appendChild(header)

        const bar = document.createElement("div")
        bar.className = "flex gap-0.5"
        GRADE_LEVELS.forEach((level) => {
            const enabled = level >= low && level <= high
            const segment = document.createElement("div")
            segment.className = `${enabled ? "bg-brand-500" : "bg-gray-200"} h-2 flex-1 rounded-full`
            bar.appendChild(segment)
        })
        wrapper.appendChild(bar)

        const labels = document.createElement("div")
        labels.className = "flex justify-between text-[10px] font-medium text-gray-400"
        GRADE_LEVELS.forEach((level) => {
            const tick = document.createElement("span")
            tick.textContent = level.toString()
            labels.appendChild(tick)
        })
        wrapper.appendChild(labels)
        return wrapper
    }

    /**
     * Extracts the Font grade level digit used by the site's grade charts.
     * @param {string} grade Grade string such as "6a+".
     * @returns {number|null} Grade level or null.
     */
    gradeLevel(grade) {
        const match = String(grade || "").match(/^[1-9]/)
        return match ? Number(match[0]) : null
    }

    /**
     * Builds a label + outbound-link row.
     * @param {string} label Row label text.
     * @param {string} linkText Link text.
     * @param {URL} url Verified HTTP(S) URL.
     * @returns {HTMLElement} Row element.
     */
    labelledLinkRow(label, linkText, url) {
        const row = document.createElement("p")
        row.className = "text-sm text-gray-700"
        if (label) row.appendChild(document.createTextNode(`${label}: `))
        row.appendChild(this.outboundLink(linkText, url, "font-medium text-brand-500 hover:underline"))
        return row
    }

